package com.profa.review;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/reviews")public class ReviewController{final ReviewRepository r;public ReviewController(ReviewRepository r){this.r=r;}@GetMapping("/teacher/{teacherId}")public List<Review> byTeacher(@PathVariable UUID teacherId){return r.findAll().stream().filter(x->teacherId.equals(x.getTeacherId())).toList();}@PostMapping public Review create(Authentication a,@RequestBody Review x){x.setAuthorId(UUID.fromString(a.getName()));if(x.getRating()<1||x.getRating()>5)throw new IllegalArgumentException("rating 1..5");return r.save(x);}}